      dialog = 3,
      music = "11_Sorrow_LongEnding_Ver",
      renwu = "npc",
      sentence = "Seeing the name \"Albus\" etched in stone, and on a street named \"Tendersweet\" no less, all seemed extraordinarily jarring.",
