    [33] = {
      beijing = 8191,
      dialog = 3,
      music = "11_Sorrow_LongEnding_Ver",
      renwu = "npc",
      sentence = "First, I squeezed him by the hand, but then I felt like this wasn't enough. Releasing my grip, I plunged into his arms and gave him a bear hug.",
