    [34] = {
      beijing = 8191,
      dialog = 3,
      music = "11_Sorrow_LongEnding_Ver",
      renwu = "npc",
      sentence = "I could never bring myself to think about that part of Gavin's childhood, when \"he\" was absent, and how much love it must have taken from his other family members to fill the void.",
